  1	// POST /groups/:id/import: records a list of expenses and payments for a group in one write, all or nothing.
  2	// Same handler contract as lib/groups.mjs: it returns the new store as `state` instead of changing the old one.
  3	import { NOT_FOUND, findGroup } from './groups.mjs'
  4	import { balances, expenseView, paymentView } from './ledger.mjs'
  5	import { parseAmount, parseDescription, parseMember, parseSplit, ValidationError } from './validate.mjs'
  6	
  7	const MAX_ENTRIES = 50
  8	// parseMember wants a message; check() swaps it for the rule name, so these only keep the POST routes' wording.
  9	const PAYER_MESSAGE = 'payer must be a member of the group'
 10	const MEMBER_MESSAGE = 'from and to must be two different members of the group'
 11	const BODY_FIELDS = ['entries', 'dry_run', 'skip_recorded']
 12	const ENTRY_FIELDS = {
 13	  expense: ['type', 'description', 'payer', 'amount', 'split'],
 14	  payment: ['type', 'from', 'to', 'amount'],
 15	}
 16	
 17	// Thrown by the entry checks with the name of the rule the entry breaks.
 18	class RuleError extends Error {}
 19	
 20	const isObject = v => v !== null && typeof v === 'object' && !Array.isArray(v)
 21	
 22	// Runs parse and returns its value; a ValidationError becomes the given rule.
 23	function check(rule, parse) {
 24	  try {
 25	    return parse()
 26	  } catch (err) {
 27	    if (err instanceof ValidationError) throw new RuleError(rule)
 28	    throw err
 29	  }
 30	}
 31	
 32	// A flag that is false when its key is absent, and must be a boolean when present.
 33	function parseFlag(body, name) {
 34	  if (!Object.hasOwn(body, name)) return false
 35	  if (typeof body[name] !== 'boolean') throw new ValidationError(`${name} must be true or false`)
 36	  return body[name]
 37	}
 38	
 39	// The body's checks, in the order the first failing one decides the 400 message.
 40	function parseBody(body) {
 41	  const unknown = Object.keys(body).find(key => !BODY_FIELDS.includes(key))
 42	  if (unknown !== undefined) throw new ValidationError(`unknown field ${unknown}`)
 43	  const { entries } = body
 44	  if (!Array.isArray(entries) || entries.length < 1 || entries.length > MAX_ENTRIES) {
 45	    throw new ValidationError(`entries must be an array of 1 to ${MAX_ENTRIES} items`)
 46	  }
 47	  return { entries, dryRun: parseFlag(body, 'dry_run'), skipRecorded: parseFlag(body, 'skip_recorded') }
 48	}
 49	
 50	// The clean { type, fields } of one entry, or a RuleError naming the first rule it breaks before `duplicate`.
 51	function parseEntry(entry, group) {
 52	  if (!isObject(entry)) throw new RuleError('not-an-object')
 53	  const { type } = entry
 54	  if (type !== 'expense' && type !== 'payment') throw new RuleError('bad-type')
 55	  if (Object.keys(entry).some(key => !ENTRY_FIELDS[type].includes(key))) throw new RuleError('unknown-field')
 56	  if (type === 'expense') {
 57	    return {
 58	      type,
 59	      fields: {
 60	        description: check('bad-description', () => parseDescription(entry.description)),
 61	        payer: check('bad-payer', () => parseMember(entry.payer, group.members, PAYER_MESSAGE)),
 62	        amount: check('bad-amount', () => parseAmount(entry.amount)),
 63	        split: check('bad-split', () => parseSplit(entry.split, group.members)),
 64	      },
 65	    }
 66	  }
 67	  const from = check('bad-from', () => parseMember(entry.from, group.members, MEMBER_MESSAGE))
 68	  const to = check('bad-to', () => parseMember(entry.to, group.members, MEMBER_MESSAGE))
 69	  if (to === from) throw new RuleError('bad-to')
 70	  return { type, fields: { from, to, amount: check('bad-amount', () => parseAmount(entry.amount)) } }
 71	}
 72	
 73	// Two expenses are the same when payer, amount in cents and trimmed, lower-cased description match.
 74	const expenseKey = ({ payer, amount, description }) =>
 75	  JSON.stringify([payer, amount, description.trim().toLowerCase()])
 76	
 77	// Sorts the entries into { problems, skipped, accepted }: one problem per entry that breaks a rule, the indexes
 78	// of the already-recorded entries skip_recorded leaves out, and the parsed entries to import, all in entry order.
 79	function sortEntries(state, group, entries, skipRecorded) {
 80	  const recorded = new Set(state.expenses.filter(e => e.group === group.id).map(expenseKey))
 81	  // Every expense that passed its field checks, so a later copy is a duplicate even of a skipped one.
 82	  const seen = new Set()
 83	  const problems = []
 84	  const skipped = []
 85	  const accepted = []
 86	  for (const [index, entry] of entries.entries()) {
 87	    let parsed
 88	    try {
 89	      parsed = parseEntry(entry, group)
 90	    } catch (err) {
 91	      if (!(err instanceof RuleError)) throw err
 92	      problems.push({ index, rule: err.message })
 93	      continue
 94	    }
 95	    if (parsed.type === 'expense') {
 96	      const key = expenseKey(parsed.fields)
 97	      const isDuplicate = seen.has(key)
 98	      seen.add(key)
 99	      if (isDuplicate) {
100	        problems.push({ index, rule: 'duplicate' })
101	        continue
102	      }
103	      if (recorded.has(key)) {
104	        if (skipRecorded) skipped.push(index)
105	        else problems.push({ index, rule: 'already-recorded' })
106	        continue
107	      }
108	    }
109	    accepted.push(parsed)
110	  }
111	  return { problems, skipped, accepted }
112	}
113	
114	// The store with the accepted entries added, each kind numbered on from its next id in entry order.
115	function addEntries(state, group, accepted) {
116	  let { nextExpenseId, nextPaymentId } = state
117	  const expenses = []
118	  const payments = []
119	  for (const { type, fields } of accepted) {
120	    if (type === 'expense') expenses.push({ id: nextExpenseId++, group: group.id, ...fields })
121	    else payments.push({ id: nextPaymentId++, group: group.id, ...fields })
122	  }
123	  const next = {
124	    ...state,
125	    expenses: [...state.expenses, ...expenses],
126	    payments: [...state.payments, ...payments],
127	    nextExpenseId,
128	    nextPaymentId,
129	  }
130	  return { expenses, payments, next }
131	}
132	
133	export function importEntries({ state, params, body }) {
134	  const group = findGroup(state, params[0])
135	  if (!group) return NOT_FOUND
136	  const { entries, dryRun, skipRecorded } = parseBody(body)
137	  const { problems, skipped, accepted } = sortEntries(state, group, entries, skipRecorded)
138	  if (problems.length > 0) return { status: 422, body: { error: 'import rejected', problems } }
139	
140	  const { expenses, payments, next } = addEntries(state, group, accepted)
141	  const reply = {
142	    expenses: expenses.map(expenseView),
143	    payments: payments.map(paymentView),
144	    skipped,
145	    balances: balances(next, group),
146	  }
147	  if (dryRun) return { status: 200, body: reply }
148	  // Nothing to record (every entry skipped): reply as a success but leave the data file alone.
149	  return { status: 201, body: reply, ...(accepted.length > 0 && { state: next }) }
150	}
151	// Input checks for request bodies and query strings. Each parser returns the clean value or throws a
152	// ValidationError, which the server turns into a 400 reply.
153	
154	export class ValidationError extends Error {
155	  constructor(message) {
156	    super(message)
157	    this.name = 'ValidationError'
158	  }
159	}
160	
161	const GROUP_ID = /^[a-z][a-z0-9-]{0,29}$/
162	const MEMBER_NAME = /^[A-Za-z][A-Za-z0-9_-]{0,29}$/
163	const MIN_MEMBERS = 2
164	const MAX_MEMBERS = 20
165	const MAX_GROUP_NAME_LENGTH = 100
166	const MAX_DESCRIPTION_LENGTH = 200
167	const CENTS_PER_UNIT = 100
168	const MAX_AMOUNT_CENTS = 1_000_000 * CENTS_PER_UNIT
169	// Digits with at most two decimals, as String() writes a number: "12", "12.5", "4.35".
170	const TWO_DECIMALS = /^[0-9]+(\.[0-9]{1,2})?$/
171	
172	const AMOUNT_MESSAGE = 'amount must be a number from 0.01 to 1000000 with at most 2 decimals'
173	const SPLIT_MESSAGE = 'split must be a non-empty list of different members of the group'
174	
175	const isText = (v, max) => typeof v === 'string' && v.trim() !== '' && v.length <= max
176	
177	export function parseGroupId(v) {
178	  if (typeof v !== 'string' || !GROUP_ID.test(v)) {
179	    throw new ValidationError('id must be 1 to 30 characters of a-z, 0-9 or -, starting with a letter')
180	  }
181	  return v
182	}
183	
184	export function parseGroupName(v) {
185	  if (!isText(v, MAX_GROUP_NAME_LENGTH)) {
186	    throw new ValidationError(`name must be a non-empty string of at most ${MAX_GROUP_NAME_LENGTH} characters`)
187	  }
188	  return v
189	}
190	
191	// A list of 2 to 20 member names, each used once. Names are case-sensitive: "Ann" and "ann" are two people.
192	export function parseMembers(v) {
193	  if (!Array.isArray(v) || v.length < MIN_MEMBERS || v.length > MAX_MEMBERS) {
194	    throw new ValidationError(`members must be an array of ${MIN_MEMBERS} to ${MAX_MEMBERS} names`)
195	  }
196	  if (!v.every(name => typeof name === 'string' && MEMBER_NAME.test(name))) {
197	    throw new ValidationError('member names must be 1 to 30 characters of A-Z, a-z, 0-9, _ or -, starting with a letter')
198	  }
199	  if (new Set(v).size !== v.length) throw new ValidationError('members must not repeat a name')
200	  return [...v]
201	}
202	
203	export function parseDescription(v) {
204	  if (!isText(v, MAX_DESCRIPTION_LENGTH)) {
205	    throw new ValidationError(`description must be a non-empty string of at most ${MAX_DESCRIPTION_LENGTH} characters`)
206	  }
207	  return v
208	}
209	
210	// Amounts arrive as numbers such as 12.5 or 4.35 and are kept as whole cents, so sums never drift.
211	export function parseAmount(v) {
212	  if (typeof v !== 'number' || !TWO_DECIMALS.test(String(v))) throw new ValidationError(AMOUNT_MESSAGE)
213	  // Rounded, not truncated: 4.35 * 100 is 434.99999999999994 in floating point.
214	  const cents = Math.round(v * CENTS_PER_UNIT)
215	  if (cents < 1 || cents > MAX_AMOUNT_CENTS) throw new ValidationError(AMOUNT_MESSAGE)
216	  return cents
217	}
218	
219	// A name that must belong to one of members; message says which field was wrong.
220	export function parseMember(v, members, message) {
221	  if (typeof v !== 'string' || !members.includes(v)) throw new ValidationError(message)
222	  return v
223	}
224	
225	// Who shares an expense: a non-empty list of members without repeats. Missing means every member, in group order.
226	export function parseSplit(v, members) {
227	  if (v === undefined) return [...members]
228	  if (!Array.isArray(v) || v.length === 0 || new Set(v).size !== v.length) throw new ValidationError(SPLIT_MESSAGE)
229	  if (!v.every(name => typeof name === 'string' && members.includes(name))) throw new ValidationError(SPLIT_MESSAGE)
230	  return [...v]
231	}
232	// Money maths on whole cents: how an expense is shared, what each member is owed or owes, and how to settle up.
233	// Amounts are stored as cents and shown by the API as numbers (435 cents is 4.35).
234	
235	const CENTS_PER_UNIT = 100
236	
237	export const toAmount = cents => cents / CENTS_PER_UNIT
238	
239	// Each person's part of an amount in cents, as [name, cents] pairs in the order of people. When the amount does
240	// not divide evenly, the first people pay one cent more each, so the parts always add up to the amount.
241	export function splitEvenly(cents, people) {
242	  const share = Math.floor(cents / people.length)
243	  const remainder = cents - share * people.length
244	  return people.map((name, i) => [name, share + (i < remainder ? 1 : 0)])
245	}
246	
247	// An expense as the API shows it: amounts as numbers, plus each person's share keyed by name.
248	export function expenseView({ id, description, payer, amount, split }) {
249	  const shares = Object.fromEntries(splitEvenly(amount, split).map(([name, cents]) => [name, toAmount(cents)]))
250	  return { id, description, payer, amount: toAmount(amount), split, shares }
251	}
252	
253	export const paymentView = ({ id, from, to, amount }) => ({ id, from, to, amount: toAmount(amount) })
254	
255	// Each member's balance in cents, as a Map in the group's member order. A payer is owed the whole expense
256	// minus their own share; a payment from A to B moves A up and B down.
257	function balanceCents(state, group) {
258	  const cents = new Map(group.members.map(name => [name, 0]))
259	  const add = (name, delta) => cents.set(name, cents.get(name) + delta)
260	  for (const expense of state.expenses.filter(e => e.group === group.id)) {
261	    add(expense.payer, expense.amount)
262	    for (const [name, share] of splitEvenly(expense.amount, expense.split)) add(name, -share)
263	  }
264	  for (const payment of state.payments.filter(p => p.group === group.id)) {
265	    add(payment.from, payment.amount)
266	    add(payment.to, -payment.amount)
267	  }
268	  return cents
269	}
270	
271	// What each member of the group is owed (positive) or owes (negative), in the group's member order.
272	export function balances(state, group) {
273	  return Object.fromEntries([...balanceCents(state, group)].map(([name, cents]) => [name, toAmount(cents)]))
274	}
275	
276	// The member furthest on one side: sign 1 is owed the most, sign -1 owes the most. Ties go to the member who
277	// comes first in the map; null when nobody is on that side.
278	function furthest(cents, sign) {
279	  let best = null
280	  for (const [name, value] of cents) {
281	    if (value * sign > 0 && (best === null || value * sign > cents.get(best) * sign)) best = name
282	  }
283	  return best
284	}
285	
286	// Payments that would bring every balance to 0, as [{from, to, amount}]: the member who owes the most pays the
287	// member who is owed the most whichever is smaller of the two, until nobody owes anything.
288	export function settleUp(state, group) {
289	  const left = balanceCents(state, group)
290	  const payments = []
291	  let from = furthest(left, -1)
292	  let to = furthest(left, 1)
293	  while (from && to) {
294	    const cents = Math.min(-left.get(from), left.get(to))
295	    payments.push({ from, to, amount: toAmount(cents) })
296	    left.set(from, left.get(from) + cents)
297	    left.set(to, left.get(to) - cents)
298	    from = furthest(left, -1)
299	    to = furthest(left, 1)
300	  }
301	  return payments
302	}
303	// Route table. `takesBody` marks the routes whose JSON body the server reads and passes on as `body`.
304	import { addExpense, addPayment, deleteExpense, editExpense, listExpenses, listPayments } from './expenses.mjs'
305	import { createGroup, getBalances, getGroup, getSettleUp } from './groups.mjs'
306	import { importEntries } from './import.mjs'
307	
308	// Checked in order; the first match wins.
309	const ROUTES = [
310	  { method: 'POST', path: /^\/groups$/, handler: createGroup, takesBody: true },
311	  { method: 'GET', path: /^\/groups\/([^/]+)$/, handler: getGroup },
312	  { method: 'GET', path: /^\/groups\/([^/]+)\/balances$/, handler: getBalances },
313	  { method: 'GET', path: /^\/groups\/([^/]+)\/settle-up$/, handler: getSettleUp },
314	  { method: 'POST', path: /^\/groups\/([^/]+)\/expenses$/, handler: addExpense, takesBody: true },
315	  { method: 'GET', path: /^\/groups\/([^/]+)\/expenses$/, handler: listExpenses },
316	  { method: 'PATCH', path: /^\/groups\/([^/]+)\/expenses\/([^/]+)$/, handler: editExpense, takesBody: true },
317	  { method: 'DELETE', path: /^\/groups\/([^/]+)\/expenses\/([^/]+)$/, handler: deleteExpense },
318	  { method: 'POST', path: /^\/groups\/([^/]+)\/payments$/, handler: addPayment, takesBody: true },
319	  { method: 'GET', path: /^\/groups\/([^/]+)\/payments$/, handler: listPayments },
320	  { method: 'POST', path: /^\/groups\/([^/]+)\/import$/, handler: importEntries, takesBody: true },
321	]
322	
323	// Returns { handler, params, takesBody } for the first route matching method and pathname, or null.
324	export function findRoute(method, pathname) {
325	  for (const { method: m, path, handler, takesBody = false } of ROUTES) {
326	    const match = m === method && path.exec(pathname)
327	    if (match) return { handler, params: match.slice(1), takesBody }
328	  }
329	  return null
330	}
331	// HTTP helpers: reading a JSON body, sending JSON replies and turning errors into replies.
332	import { ValidationError } from './validate.mjs'
333	
334	export const MAX_BODY_BYTES = 10 * 1024
335	
336	export class HttpError extends Error {
337	  constructor(status, message) {
338	    super(message)
339	    this.status = status
340	  }
341	}
342	
343	// Reads the whole body as UTF-8. Past MAX_BODY_BYTES it stops keeping chunks but still drains the upload,
344	// so the 413 reply reaches the client instead of a reset connection.
345	export function readBody(req) {
346	  return new Promise((resolve, reject) => {
347	    const chunks = []
348	    let size = 0
349	    req.on('data', chunk => {
350	      size += chunk.length
351	      if (size <= MAX_BODY_BYTES) chunks.push(chunk)
352	    })
353	    req.on('end', () => {
354	      if (size > MAX_BODY_BYTES) reject(new HttpError(413, 'body too large'))
355	      else resolve(Buffer.concat(chunks).toString('utf8'))
356	    })
357	    req.on('error', reject)
358	  })
359	}
360	
361	export function parseJsonObject(text) {
362	  let value
363	  try {
364	    value = JSON.parse(text)
365	  } catch {
366	    throw new HttpError(400, 'invalid JSON')
367	  }
368	  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
369	    throw new HttpError(400, 'body must be a JSON object')
370	  }
371	  return value
372	}
373	
374	// Sends { status, body }: body as JSON, or no body at all when it is undefined (204).
375	export function send(res, { status, body }) {
376	  if (body === undefined) {
377	    res.writeHead(status).end()
378	    return
379	  }
380	  const text = JSON.stringify(body)
381	  res.writeHead(status, { 'content-type': 'application/json', 'content-length': Buffer.byteLength(text) })
382	  res.end(text)
383	}
384	
385	export function errorReply(err) {
386	  if (err instanceof HttpError) return { status: err.status, body: { error: err.message } }
387	  if (err instanceof ValidationError) return { status: 400, body: { error: err.message } }
388	  // An OS error (ENOENT, EACCES, ...) is logged as one line; any other error keeps its stack.
389	  console.error(err.code ? [err.code, err.syscall, err.path].filter(Boolean).join(' ') : err)
390	  return { status: 500, body: { error: 'internal error' } }
391	}

1	import { mkdtempSync, rmSync } from 'node:fs'
2	import { tmpdir } from 'node:os'
3	import { join } from 'node:path'
4	import { createApp } from '../server.mjs'
5	
6	// A data file in a fresh temp folder; cleanup() deletes the folder.
7	export function tempDataFile() {
8	  const dir = mkdtempSync(join(tmpdir(), 'split-test-'))
9	  return { file: join(dir, 'groups.json'), cleanup: () => rmSync(dir, { recursive: true, force: true }) }
10	}
11	
12	// Starts the app on a free port. call(method, path, body) sends one request; stop() closes the server.
13	export async function startApp(dataFile) {
14	  const server = createApp(dataFile)
15	  await new Promise((resolve, reject) => {
16	    server.once('error', reject)
17	    server.listen(0, '127.0.0.1', resolve)
18	  })
19	  const base = `http://127.0.0.1:${server.address().port}`
20	  return {
21	    call: (method, path, body) => request(base + path, method, body),
22	    stop: () => new Promise(resolve => server.close(resolve)),
23	  }
24	}
25	
26	// Runs fn with a running app on its own data file, then stops it and deletes the file.
27	export async function withApp(fn) {
28	  const data = tempDataFile()
29	  const app = await startApp(data.file)
30	  try {
31	    await fn(app.call)
32	  } finally {
33	    await app.stop()
34	    data.cleanup()
35	  }
36	}
37	
38	async function request(url, method, body) {
39	  const init = { method }
40	  if (body !== undefined) {
41	    init.headers = { 'content-type': 'application/json' }
42	    init.body = typeof body === 'string' ? body : JSON.stringify(body)
43	  }
44	  const res = await fetch(url, init)
45	  const text = await res.text()
46	  const isJson = (res.headers.get('content-type') ?? '').startsWith('application/json')
47	  return { status: res.status, headers: res.headers, text, body: isJson ? JSON.parse(text) : undefined }
48	}
